import React, { useState } from 'react';

export default function ProjectCard({ project, index }) {
  const [hovered, setHovered] = useState(false);
  const isLive = project.status === 'live';
  const [g1, g2] = project.gradient;

  const handleClick = () => {
    if (isLive && project.url) window.open(project.url, '_blank', 'noopener,noreferrer');
  };

  return (
    <div
      onClick={handleClick}
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
      style={{
        position: 'relative',
        background: hovered && isLive
          ? 'linear-gradient(145deg, #1E2435, #252A3A)'
          : 'linear-gradient(145deg, #161B28, #1C2130)',
        border: hovered && isLive
          ? `1px solid rgba(255,255,255,0.14)`
          : '1px solid rgba(255,255,255,0.06)',
        borderRadius: 20,
        padding: '1.5rem',
        cursor: isLive ? 'pointer' : 'default',
        opacity: isLive ? 1 : 0.55,
        transform: hovered && isLive ? 'translateY(-6px) scale(1.01)' : 'translateY(0) scale(1)',
        boxShadow: hovered && isLive
          ? `0 20px 50px rgba(0,0,0,0.5), 0 0 0 1px rgba(255,255,255,0.06), inset 0 1px 0 rgba(255,255,255,0.08)`
          : '0 4px 16px rgba(0,0,0,0.3)',
        transition: 'all 0.25s cubic-bezier(0.34, 1.56, 0.64, 1)',
        animation: `fadeUp 0.45s ease both`,
        animationDelay: `${index * 80}ms`,
        overflow: 'hidden',
      }}
    >
      {/* Glow blob on hover */}
      {isLive && (
        <div style={{
          position: 'absolute',
          top: -30, right: -30,
          width: 120, height: 120,
          borderRadius: '50%',
          background: `radial-gradient(circle, ${g1}33, transparent 70%)`,
          opacity: hovered ? 1 : 0,
          transition: 'opacity 0.3s ease',
          pointerEvents: 'none',
        }} />
      )}

      {/* Top row: icon + tag */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '1.1rem' }}>
        <div style={{
          width: 52, height: 52,
          borderRadius: 14,
          background: `linear-gradient(135deg, ${g1}, ${g2})`,
          display: 'flex', alignItems: 'center', justifyContent: 'center',
          boxShadow: `0 6px 20px ${g1}55`,
        }}>
          <i className={`ti ${project.icon}`} style={{ fontSize: 26, color: '#fff' }} />
        </div>

        <span style={{
          fontSize: 11,
          fontWeight: 600,
          letterSpacing: 0.8,
          textTransform: 'uppercase',
          color: g1,
          background: `${g1}18`,
          border: `1px solid ${g1}33`,
          padding: '3px 10px',
          borderRadius: 20,
        }}>
          {project.tag}
        </span>
      </div>

      {/* Name */}
      <div style={{
        fontSize: 16,
        fontWeight: 700,
        color: '#F0F0F0',
        marginBottom: 6,
        fontFamily: 'Outfit, sans-serif',
        letterSpacing: -0.2,
      }}>
        {project.name}
      </div>

      {/* Description */}
      <div style={{
        fontSize: 13,
        color: '#6B7280',
        lineHeight: 1.55,
        marginBottom: '1.2rem',
      }}>
        {project.description}
      </div>

      {/* Bottom: status + open arrow */}
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
          <span style={{
            width: 8, height: 8, borderRadius: '50%',
            background: isLive ? '#10B981' : '#F59E0B',
            display: 'inline-block',
            boxShadow: isLive ? '0 0 0 3px rgba(16,185,129,0.2)' : '0 0 0 3px rgba(245,158,11,0.2)',
          }} />
          <span style={{ fontSize: 12, fontWeight: 600, color: isLive ? '#10B981' : '#F59E0B' }}>
            {isLive ? 'Live' : 'Coming Soon'}
          </span>
        </div>

        {isLive && (
          <div style={{
            width: 32, height: 32, borderRadius: 10,
            background: hovered ? `linear-gradient(135deg, ${g1}, ${g2})` : 'rgba(255,255,255,0.06)',
            display: 'flex', alignItems: 'center', justifyContent: 'center',
            transition: 'background 0.2s ease',
          }}>
            <i className="ti ti-arrow-up-right" style={{
              fontSize: 16,
              color: hovered ? '#fff' : '#4B5563',
              transition: 'color 0.2s ease',
            }} />
          </div>
        )}
      </div>
    </div>
  );
}
